import argparse


def main(argv=None):
    parser = argparse.ArgumentParser(description="Print a greeting.")
    parser.add_argument("--verbose", action="store_true", help="print details")
    args = parser.parse_args(argv)
    if args.verbose:
        print("starting")
    print("hello")


if __name__ == "__main__":
    main()
